from collections import Counter

def check_similar_times(tuples):
    counts = Counter(tuples)
    return {t: c for t, c in counts.items() if c > 1}
```

```python
def largest_adjacent_product(nums):
    if len(nums) < 2:
        return None
    return max(nums[i] * nums[i + 1] for i in range(len(nums) - 1))
```
